from fractions import Fraction as F
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
names='TUVW'; costs=list(map(F,['0.8','1.2','0.7','1.4']))
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in ids),w),'ABCD'[a]) for a in range(4))
def solve(ids,available,k):
 best=stop(ids)
 if k:
  for t in available:
   val=costs[t]; w=sum(rows[i][1] for i in ids)
   for r in (0,1):
    sub=[i for i in ids if rows[i][2][t]==r]
    if sub: val+=F(sum(rows[i][1] for i in sub),w)*solve(sub,[j for j in available if j!=t],k-1)[0]
   best=min(best,(val,names[t]))
 return best
ids=list(range(8)); total=sum(r[1] for r in rows)
first_losses={'STOP':float(stop(ids)[0])}
for t in range(4):
 val=costs[t]
 for r in (0,1):
  sub=[i for i in ids if rows[i][2][t]==r]
  if sub:val+=F(sum(rows[i][1] for i in sub),total)*solve(sub,[j for j in range(4) if j!=t],1)[0]
 first_losses[names[t]]=float(val)
best=solve(ids,list(range(4)),2)
next_actions={}
if best[1] in names:
 t=names.index(best[1])
 for r in (0,1):
  sub=[i for i in ids if rows[i][2][t]==r]
  next_actions[str(r)]=solve(sub,[j for j in range(4) if j!=t],1)[1] if sub else 'IMPOSSIBLE'
print({'first':best[1],'first_losses':first_losses,'next':next_actions})

