from fractions import Fraction as F
# V=0 rows; redisplay of stored value supplies no additional evidence.
rows=[('A',15,(1,0,1)),('B',6,(1,0,0)),('B',5,(0,1,0)),('D',14,(0,0,0))]
L={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
mods='ABCD'; tests='TUW'; costs=[F('0.8'),F('1.2'),F('7.4')]
def repairs(rs):
 w=sum(r[1] for r in rs)
 return {a:F(sum(r[1]*v[mods.index(r[0])] for r in rs),w) for a,v in L.items()}
remaining=repairs(rows); branches={}
for j,t in enumerate(tests):
 value=costs[j]; branches[t]={}
 for outcome in (0,1):
  rs=[r for r in rows if r[2][j]==outcome]
  if not rs: branches[t][str(outcome)]='IMPOSSIBLE';continue
  losses=repairs(rs); a=min(losses,key=losses.get)
  branches[t][str(outcome)]=a
  value+=F(sum(r[1] for r in rs),40)*losses[a]
 remaining[t]=value
a=min(remaining,key=remaining.get)
print({'posterior':{m:sum(r[1] for r in rows if r[0]==m)/40 for m in mods},'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':a,'repair_after':branches.get(a,{})})

